def priority(item: float, bins: np.ndarray) -> np.ndarray:
    target_fill = 0.6
    fill_ratio = item / bins
    return np.where(bins >= item, -np.abs(fill_ratio - target_fill), -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    fit_mask = bins >= item
    remaining_space = np.where(fit_mask, bins - item, 0.0)
    target_fill = bins / 2.0
    deviation = remaining_space - target_fill
    return np.where(fit_mask, - (deviation ** 2), -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    fit_mask = bins >= item
