def priority(item: float, bins: np.ndarray) -> np.ndarray:
    fit_mask = bins >= item
    remaining_space = np.where(fit_mask, bins - item, 0.0)
    target_fill = bins * 0.6  # Target fill level set to 60% of bin capacity
    deviation = np.abs(remaining_space - target_fill)
    return np.where(fit_mask, -deviation, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    fit_mask = bins >= item
    remaining_space = np.where(fit_mask, bins - item, 0.0)
    target = 2 * item
    deviation = remaining_space - target
    return np.where(fit_mask, - (deviation ** 2), -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - np.minimum(bins, item)
    return remaining
